import { readFileSync } from "node:fs";

/** A Merkle proof as emitted by `tools/fri-vectors`, with scalars converted to bigints. */
export interface LeafProof {
  leaf: bigint[];
  path: string[];
}

export interface FriFold {
  left: LeafProof;
  right: LeafProof;
}

export interface FriQuery {
  index: bigint;
  folds: FriFold[];
}

/** A FRI test case generated by `starkom-pcs` with the Keccak-256 backend over BlueSky. */
export interface FriCase {
  name: string;
  degreeBound: bigint;
  blowupLog2: bigint;
  roots: string[];
  queries: FriQuery[];
}

interface RawLeafProof {
  leaf: string[];
  path: string[];
}

interface RawCase {
  name: string;
  degreeBound: number;
  blowupLog2: number;
  roots: string[];
  queries: {
    index: number;
    folds: { left: RawLeafProof; right: RawLeafProof }[];
  }[];
}

function convertLeafProof(proof: RawLeafProof): LeafProof {
  return { leaf: proof.leaf.map(BigInt), path: proof.path };
}

/** Loads the FRI test vectors generated by `tools/fri-vectors`. */
export function loadFriCases(): FriCase[] {
  const raw: RawCase[] = JSON.parse(
    readFileSync(new URL("./vectors/fri.json", import.meta.url), "utf8")
  );
  return raw.map((testCase) => ({
    name: testCase.name,
    degreeBound: BigInt(testCase.degreeBound),
    blowupLog2: BigInt(testCase.blowupLog2),
    roots: testCase.roots,
    queries: testCase.queries.map((query) => ({
      index: BigInt(query.index),
      folds: query.folds.map((fold) => ({
        left: convertLeafProof(fold.left),
        right: convertLeafProof(fold.right),
      })),
    })),
  }));
}
